.profile-settings {
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    background: var(--g-color-base-background);
}

.profile-settings__content {
    box-sizing: border-box;
    width: 100%;
    max-width: 880px;
    margin-inline: auto;
    padding: var(--g-spacing-6) var(--g-spacing-4);
}

/* FormRow ships with margin-block-end on every row; drop it on the last row of a section. */
.profile-settings__row:last-child {
    margin-block-end: 0;
}

/* FormRow's label column is 172px by default — widen it for longer Russian labels. */
.profile-settings__row {
    --gc-form-row-label-width: 220px;
}

.profile-settings__footer {
    position: sticky;
    bottom: 0;
    margin-top: auto;
    border-top: 1px solid var(--g-color-line-generic);
    background: var(--g-color-base-background);
}

.profile-settings__footer .profile-settings__content {
    padding-block: var(--g-spacing-3);
}

.profile-settings__hint {
    flex: 1;
    min-width: 0;
}

@media (max-width: 575px) {
    .profile-settings__hint {
        display: none;
    }
}

